export interface Request {
  path: string;
}

export interface Reply {
  send(body: unknown): void;
}

export type Handler = (request: Request, reply: Reply) => void;

/** What `App.at` returns: the verbs registered on one path. */
export interface Route {
  get(...handlers: Handler[]): this;
  post(...handlers: Handler[]): this;
  delete(...handlers: Handler[]): this;
}

export interface App {
  get(path: string, ...handlers: Handler[]): this;
  /** Serves `child`'s routes under `prefix`. */
  use(prefix: string, child: App): this;
  /** The verbs registered on `path`. */
  at(path: string): Route;
}

declare function app(): App;
export default app;
